    66→#[test]
    67→fn eip_4788_non_genesis_call() {
    68→    let mut header =
    69→        Header { timestamp: 1, number: 1, excess_blob_gas: Some(0), ..Header::default() };
    70→
    71→    let db = create_database_with_beacon_root_contract();
    72→
    73→    let chain_spec = Arc::new(
    74→        ChainSpecBuilder::from(&*MAINNET)
    75→            .shanghai_activated()
    76→            .with_fork(EthereumHardfork::Cancun, ForkCondition::Timestamp(1))
    77→            .build(),
    78→    );
    79→
    80→    let provider = EthEvmConfig::new(chain_spec);
    81→
    82→    let mut executor = BasicBlockExecutor::new(provider, db);
    83→
    84→    // attempt to execute a block without parent beacon block root, expect err
    85→    let err = executor
    86→        .execute_one(&RecoveredBlock::new_unhashed(
    87→            Block {
    88→                header: header.clone(),
    89→                body: BlockBody { transactions: vec![], ommers: vec![], withdrawals: None },
    90→            },
    91→            vec![],
    92→        ))
    93→        .expect_err("Executing cancun block without parent beacon block root field should fail");
    94→
    95→    assert!(matches!(
    96→        err.as_validation().unwrap(),
    97→        BlockValidationError::MissingParentBeaconBlockRoot
    98→    ));
    99→
   100→    // fix header, set a gas limit
   101→    header.parent_beacon_block_root = Some(B256::with_last_byte(0x69));
   102→
   103→    // Now execute a block with the fixed header, ensure that it does not fail
   104→    executor
   105→        .execute_one(&RecoveredBlock::new_unhashed(
   106→            Block {
   107→                header: header.clone(),
   108→                body: BlockBody { transactions: vec![], ommers: vec![], withdrawals: None },
   109→            },
   110→            vec![],
   111→        ))
   112→        .unwrap();
   113→
   114→    // check the actual storage of the contract - it should be:
   115→    // * The storage value at header.timestamp % HISTORY_BUFFER_LENGTH should be
   116→    // header.timestamp
   117→    // * The storage value at header.timestamp % HISTORY_BUFFER_LENGTH + HISTORY_BUFFER_LENGTH //
   118→    //   should be parent_beacon_block_root
   119→    let history_buffer_length = 8191u64;
   120→    let timestamp_index = header.timestamp % history_buffer_length;
   121→    let parent_beacon_block_root_index =
   122→        timestamp_index % history_buffer_length + history_buffer_length;
   123→
   124→    let timestamp_storage = executor.with_state_mut(|state| {
   125→        state.storage(BEACON_ROOTS_ADDRESS, U256::from(timestamp_index)).unwrap()
   126→    });
   127→    assert_eq!(timestamp_storage, U256::from(header.timestamp));
   128→
   129→    // get parent beacon block root storage and compare
   130→    let parent_beacon_block_root_storage = executor.with_state_mut(|state| {
   131→        state
   132→            .storage(BEACON_ROOTS_ADDRESS, U256::from(parent_beacon_block_root_index))
   133→            .expect("storage value should exist")
   134→    });
   135→    assert_eq!(parent_beacon_block_root_storage, U256::from(0x69));
   136→}
