   340→        code: Some(Bytecode::new_raw(HISTORY_STORAGE_CODE.clone())),
   341→        nonce: 1,
   342→    };
   343→
   344→    db.insert_account_info(HISTORY_STORAGE_ADDRESS, blockhashes_contract_account);
   345→
   346→    db
   347→}
