   535→
   536→    // nothing should be written as the genesis has no ancestors
   537→    //
   538→    // we load the account first, because revm expects it to be
   539→    // loaded
   540→    executor.with_state_mut(|state| state.basic(HISTORY_STORAGE_ADDRESS).unwrap());
   541→    assert!(executor.with_state_mut(|state| {
